# Introduction
The GDS API are interfaces to allow you to access our system using your OTA account. We provide a number of functions divided into these categories:

  - [Partner](#tag/Partner) - Get a list of suppliers and OTAs. 
  - [Activity](#tag/Activity) - Search activities and get detailed activity information. 
  - [Availability](#tag/Availability) - Get availability calendar and check availability for a request date.
  - [Booking](#tag/Booking) - Create, modify, cancel a booking.

> Using an AI coding agent to integrate? Install the [GDS API agent skill](https://github.com/linktivity/gds-neo-agent-skill) for signature debugging, endpoint reference, and booking-flow guidance grounded in this spec.

# Authentication
The GDS API uses API Key Authentication. This request authentication method require 5 custom headers:
  - `timestamp`
  - `ota-id`
  - `group-id`
  - `api-key-id`
  - `signature-key`

## Signature Algorithm

`signature-key` is a chained **HMAC-SHA256** over your secret API key, the request `timestamp`, the request `host`, and the request `path`, finalised with a fixed salt, then base64-url encoded (with `=` padding).

```
k1 = HMAC-SHA256( key = "congaree" + apiKeySecret, msg = timestamp )
k2 = HMAC-SHA256( key = k1,                         msg = host      )
k3 = HMAC-SHA256( key = k2,                         msg = path      )
k  = HMAC-SHA256( key = k3,                         msg = "veltra"  )
signatureKey = base64url(k)        # keep '=' padding
```

Inputs:

| Name | Source |
| --- | --- |
| `apiKeySecret` | The secret paired with your `api-key-id` (out-of-band issued) |
| `timestamp` | Same value as the `timestamp` header, e.g. `20260521T063324Z` |
| `host` | Request host, e.g. `open-agent.gds-neo.link-dev.link` |
| `path` | Request path only, e.g. `/v1/activity/search-activities` (no query string, no fragment) |

### Reference implementation

```go
func signatureKey(apiKeySecret, timestamp, host, path string) string {
    h := func(key, msg []byte) []byte {
        m := hmac.New(sha256.New, key)
        m.Write(msg)
        return m.Sum(nil)
    }
    k1 := h([]byte("congaree"+apiKeySecret), []byte(timestamp))
    k2 := h(k1, []byte(host))
    k3 := h(k2, []byte(path))
    k  := h(k3, []byte("veltra"))
    return base64.URLEncoding.EncodeToString(k)
}
```

## Client snippets

Self-contained, runnable examples in several languages.

**JavaScript (Postman pre-request)**

```js
// Postman pre-request script.
// Sets the `timestamp` and `signature-key` headers for GDS API requests.

const apiKey = "YOUR_API_KEY";

// Resolve Postman variables; strip any scheme from host, normalize path.
const host = pm.variables.replaceIn(pm.request.url.getHost()).replace(/^https?:\/\//i, "");
const path = pm.variables.replaceIn("/" + pm.request.url.getPath()).replace(/\/+/g, "/");

// UTC timestamp in YYYYMMDDTHHMMSSZ format.
const timestamp = new Date().toISOString().replace(/[-:]|\.\d+/g, "");

// Chained HMAC-SHA256.
const hmac = (key, msg) => CryptoJS.HmacSHA256(msg, key);
const k1 = hmac("congaree" + apiKey, timestamp);
const k2 = hmac(k1, host);
const k3 = hmac(k2, path);
const k  = hmac(k3, "veltra");

// Base64 URL-safe encoding. Keep the "=" padding; the server requires it.
const signature = CryptoJS.enc.Base64.stringify(k)
    .replace(/\+/g, "-")
    .replace(/\//g, "_");

pm.request.headers.upsert({ key: "timestamp",     value: timestamp });
pm.request.headers.upsert({ key: "signature-key", value: signature });
```

**Go**

```go
package main

import (
    "crypto/hmac"
    "crypto/sha256"
    "encoding/base64"
    "fmt"
    "io"
    "net/http"
    "time"
)

// Compute the `signature-key` header value for a GDS API request.
// The algorithm chains HMAC-SHA256 four times, then base64-URL encodes the result.
func signatureKey(apiKey, timestamp, host, path string) string {
    hmacSHA256 := func(key, msg []byte) []byte {
        h := hmac.New(sha256.New, key)
        h.Write(msg)
        return h.Sum(nil)
    }
    k1 := hmacSHA256([]byte("congaree"+apiKey), []byte(timestamp))
    k2 := hmacSHA256(k1, []byte(host))
    k3 := hmacSHA256(k2, []byte(path))
    k  := hmacSHA256(k3, []byte("veltra"))
    // Keep the "=" padding; the server requires it.
    return base64.URLEncoding.EncodeToString(k)
}

func main() {
    const (
        apiKey = "YOUR_API_KEY"
        host   = "open-agent.gds-neo.link-dev.link"
        path   = "/v1/activity/search-activities"
    )
    timestamp := time.Now().UTC().Format("20060102T150405Z")
    sig := signatureKey(apiKey, timestamp, host, path)

    req, _ := http.NewRequest("GET", "https://"+host+path+"?page_size=20", nil)
    req.Header.Set("ota-id", "LINKTIVITY")
    req.Header.Set("group-id", "[default-group]:LINKTIVITY")
    req.Header.Set("api-key-id", "VJgSBDVXXXXXXXXX")
    req.Header.Set("timestamp", timestamp)
    req.Header.Set("signature-key", sig)

    resp, err := http.DefaultClient.Do(req)
    if err != nil {
        panic(err)
    }
    defer resp.Body.Close()
    body, _ := io.ReadAll(resp.Body)
    fmt.Println(string(body))
}
```

**Python**

```python
import base64
import hashlib
import hmac
import time
import urllib.request

API_KEY = "YOUR_API_KEY"
HOST    = "open-agent.gds-neo.link-dev.link"
PATH    = "/v1/activity/search-activities"


def signature_key(api_key: str, timestamp: str, host: str, path: str) -> str:
    """Compute the `signature-key` header value for a GDS API request."""
    def hmac_sha256(key: bytes, msg: bytes) -> bytes:
        return hmac.new(key, msg, hashlib.sha256).digest()

    k1 = hmac_sha256(b"congaree" + api_key.encode(), timestamp.encode())
    k2 = hmac_sha256(k1, host.encode())
    k3 = hmac_sha256(k2, path.encode())
    k  = hmac_sha256(k3, b"veltra")
    # Keep the "=" padding; the server requires it.
    return base64.urlsafe_b64encode(k).decode()


def main():
    timestamp = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
    sig = signature_key(API_KEY, timestamp, HOST, PATH)

    req = urllib.request.Request(
        f"https://{HOST}{PATH}?page_size=20",
        headers={
            "ota-id":        "LINKTIVITY",
            "group-id":      "[default-group]:LINKTIVITY",
            "api-key-id":    "VJgSBDVXXXXXXXXX",
            "timestamp":     timestamp,
            "signature-key": sig,
        },
    )
    with urllib.request.urlopen(req) as resp:
        print(resp.read().decode())


if __name__ == "__main__":
    main()
```

**Java**

```java
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.Base64;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class SignatureExample {
    private static final String API_KEY = "YOUR_API_KEY";
    private static final String HOST    = "open-agent.gds-neo.link-dev.link";
    private static final String PATH    = "/v1/activity/search-activities";

    /** Compute the `signature-key` header value for a GDS API request. */
    static String signatureKey(String apiKey, String timestamp, String host, String path) throws Exception {
        byte[] k1 = hmacSha256(("congaree" + apiKey).getBytes(StandardCharsets.UTF_8), timestamp.getBytes(StandardCharsets.UTF_8));
        byte[] k2 = hmacSha256(k1, host.getBytes(StandardCharsets.UTF_8));
        byte[] k3 = hmacSha256(k2, path.getBytes(StandardCharsets.UTF_8));
        byte[] k  = hmacSha256(k3, "veltra".getBytes(StandardCharsets.UTF_8));
        // Keep the "=" padding; the server requires it.
        return Base64.getUrlEncoder().encodeToString(k);
    }

    private static byte[] hmacSha256(byte[] key, byte[] msg) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(key, "HmacSHA256"));
        return mac.doFinal(msg);
    }

    public static void main(String[] args) throws Exception {
        String timestamp = DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss'Z'").withZone(ZoneOffset.UTC).format(Instant.now());
        String sig = signatureKey(API_KEY, timestamp, HOST, PATH);

        HttpRequest req = HttpRequest.newBuilder()
            .uri(URI.create("https://" + HOST + PATH + "?page_size=20"))
            .header("ota-id", "LINKTIVITY")
            .header("group-id", "[default-group]:LINKTIVITY")
            .header("api-key-id", "VJgSBDVXXXXXXXXX")
            .header("timestamp", timestamp)
            .header("signature-key", sig)
            .GET()
            .build();

        HttpResponse<String> resp = HttpClient.newHttpClient().send(req, HttpResponse.BodyHandlers.ofString());
        System.out.println(resp.body());
    }
}
```

**PHP**

```php
<?php
$apiKey = 'YOUR_API_KEY';
$host   = 'open-agent.gds-neo.link-dev.link';
$path   = '/v1/activity/search-activities';

/**
 * Compute the `signature-key` header value for a GDS API request.
 */
function signatureKey(string $apiKey, string $timestamp, string $host, string $path): string {
    $hmacSha256 = fn($key, $msg) => hash_hmac('sha256', $msg, $key, true);

    $k1 = $hmacSha256('congaree' . $apiKey, $timestamp);
    $k2 = $hmacSha256($k1, $host);
    $k3 = $hmacSha256($k2, $path);
    $k  = $hmacSha256($k3, 'veltra');

    // URL-safe base64; keep the "=" padding (server requires it).
    return strtr(base64_encode($k), '+/', '-_');
}

$timestamp = gmdate('Ymd\THis\Z');
$sig = signatureKey($apiKey, $timestamp, $host, $path);

$ch = curl_init("https://{$host}{$path}?page_size=20");
curl_setopt($ch, CURLOPT_HTTPHEADER, [
    "ota-id: LINKTIVITY",
    "group-id: [default-group]:LINKTIVITY",
    "api-key-id: VJgSBDVXXXXXXXXX",
    "timestamp: {$timestamp}",
    "signature-key: {$sig}",
]);
curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
echo curl_exec($ch);
curl_close($ch);
```

### End-to-end curl example

A canonical request with all 5 headers filled in:

```bash
curl https://open-agent.gds-neo.link-dev.link/v1/activity/search-activities?page_size=20 \
  --header 'ota-id: LINKTIVITY' \
  --header 'group-id: [default-group]:LINKTIVITY' \
  --header 'api-key-id: VJgSBDVxxxxxxxxx' \
  --header 'timestamp: 20260521T063324Z' \
  --header 'signature-key: 3gjtSDLmvsr4M6RdQ9vY5sYPZ1Y7iV...='
```

### Common errors

| HTTP | Cause |
| --- | --- |
| `401 invalid api-key-id` | `api-key-id` header missing or unknown |
| `401 invalid signature` | HMAC mismatch — check `host` / `path` exactly match the request line, and `timestamp` is the same string in header and HMAC input |
| `401 timestamp out of range` | Server clock differs from `timestamp` by more than ±5 minutes; sync your clock to NTP |

